from pathlib import Path

p = Path('src/App.tsx')
s = p.read_text(encoding='utf-8')

start = s.index('      {panelEditor && activeProject ? (()=>{')
end = s.index('      {panel ? <div className="overlay"', start)

new = '''      {panelEditor && activeProject ? (()=>{const pg=activeProject.pages.find(x=>x.id===panelEditor.pageId),pl=pg?.placements.find(x=>x.id===panelEditor.placementId);if(!pg||!pl)return null;const o=(pl.overlays??[]).find(item=>item.id===selectedOverlayId)??null;return <div className="panel-editor-backdrop" onPointerDown={(e)=>e.target===e.currentTarget&&setPanelEditor(null)}><section className="panel-editor-modal"><header><div><p className="eyebrow">PANELREDIGERARE</p><h2>Sida {pg.number} · ruta {pl.readingOrder}</h2></div><div className="panel-editor-header-actions"><button className="primary-button compact-button" type="button" onClick={()=>addOverlay(pg.id,pl.id,"speech")}>Lägg till textruta</button><button className="text-button" onClick={()=>setPanelEditor(null)}>Stäng</button></div></header><div className="panel-editor-layout"><div className="panel-editor-stage">{pl.image?<img src={pl.image.dataUrl} alt="" />:<div className="panel-editor-empty">Ingen bild uppladdad</div>}<svg viewBox="0 0 100 100" preserveAspectRatio="none">{(pl.overlays??[]).map((item)=>{const selected=item.id===selectedOverlayId;return <g key={item.id} className={selected?"editable-overlay is-selected":"editable-overlay"}><g className="overlay-drag-surface" onPointerDown={(e)=>{setSelectedOverlayId(item.id);beginOverlayDrag(e,pg.id,pl.id,item,"move");}}><SvgOverlay overlay={item}/></g>{selected?<><rect className="overlay-selection-frame" x={item.x} y={item.y} width={item.width} height={item.height} rx="1"/><rect className="overlay-resize-grip" x={item.x+item.width-1.5} y={item.y+item.height-1.5} width="3" height="3" rx=".5" onPointerDown={(e)=>beginOverlayDrag(e,pg.id,pl.id,item,"resize")}/>{item.type==="speech"&&item.tailEnabled!==false&&item.tailX!==undefined&&item.tailY!==undefined?<circle className="overlay-tail-grip" cx={item.tailX} cy={item.tailY} r="1.6" onPointerDown={(e)=>beginOverlayDrag(e,pg.id,pl.id,item,"tail")}/>:null}</>:null}</g>})}</svg></div><aside className="panel-editor-tools"><p className="eyebrow">{o?"EGENSKAPER":"TEXTLAGER"}</p>{o?<div className="panel-tool-card selected-panel-tool"><div className="panel-tool-title"><strong>{o.type==="speech"?"Pratbubbla":o.type==="thought"?"Tankebubbla":o.type==="caption"?"Berättarruta":"Ljudeffekt"}</strong><button className="text-button danger-text" type="button" onClick={()=>deleteOverlay(pg.id,pl.id,o.id)}>Ta bort</button></div><label>Typ<select value={o.type} onChange={(e)=>{const type=e.target.value as OverlayType;updateOverlay(pg.id,pl.id,o.id,{type,tailEnabled:type==="speech",tailX:type==="speech"?(o.tailX??o.x+o.width*.65):undefined,tailY:type==="speech"?(o.tailY??o.y+o.height*1.15):undefined,roundness:type==="caption"?(o.roundness??18):(o.roundness??60)});}}><option value="speech">Pratbubbla</option><option value="caption">Berättarruta</option><option value="thought">Tankebubbla</option><option value="sfx">SFX</option></select></label><label>Rundning<input className="numeric-field" type="number" min="0" max="100" value={o.roundness??(o.type==="caption"?18:60)} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{roundness:Math.max(0,Math.min(100,Number(e.target.value)||0))})}/></label><label>Text<textarea rows={4} value={o.text} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{text:e.target.value})}/></label><label>Font<select value={o.fontFamily??"Comic Neue, sans-serif"} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{fontFamily:e.target.value})}><option value="Comic Neue, sans-serif">Comic Neue</option><option value="Arial, sans-serif">Arial</option><option value="Georgia, serif">Georgia</option><option value="Impact, sans-serif">Impact</option></select></label><div className="type-secondary-grid"><label>Vikt<select value={o.fontWeight??600} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{fontWeight:Number(e.target.value)})}><option value="400">400 Normal</option><option value="500">500 Medium</option><option value="600">600 Semi-bold</option><option value="700">700 Bold</option><option value="800">800 Extra-bold</option><option value="900">900 Black</option></select></label><label>Storlek<input className="numeric-field" type="number" min="1" max="120" step="0.5" value={o.fontSize??8} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{fontSize:Math.max(1,Math.min(120,Number(e.target.value)||1))})}/></label></div>{o.type==="speech"?<><label className="tail-toggle"><input type="checkbox" checked={o.tailEnabled!==false} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{tailEnabled:e.target.checked,tailX:e.target.checked?(o.tailX??o.x+o.width*.65):o.tailX,tailY:e.target.checked?(o.tailY??o.y+o.height*1.15):o.tailY})}/> Svans</label>{o.tailEnabled!==false?<div className="tail-settings-grid"><label>Böjning<input className="numeric-field" type="number" min="-100" max="100" value={o.tailCurve??0} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{tailCurve:Math.max(-100,Math.min(100,Number(e.target.value)||0))})}/></label><label>Rotbredd<input className="numeric-field" type="number" min="0" max="100" value={o.tailRootWidth??50} onChange={(e)=>updateOverlay(pg.id,pl.id,o.id,{tailRootWidth:Math.max(0,Math.min(100,Number(e.target.value)||0))})}/></label></div>:null}</>:null}</div>:<div className="panel-editor-empty-properties"><p>Välj en textruta direkt i bilden för att redigera den.</p><p className="quiet">Skapa en ny med knappen ovan om panelen ännu saknar text.</p></div>}</aside></div></section></div>})() : null}\n'''

s = s[:start] + new + s[end:]
p.write_text(s, encoding='utf-8')

css = Path('src/panelEditorOverrides.css')
c = css.read_text(encoding='utf-8')
c += '''\n.panel-editor-header-actions{display:flex;align-items:center;gap:10px}\n.panel-editor-tools>.eyebrow{margin:0 0 12px}\n.panel-editor-tools .selected-panel-tool{display:grid;gap:12px}\n.panel-editor-tools textarea{min-height:7.5rem;resize:vertical;white-space:pre-wrap}\n.type-secondary-grid,.tail-settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 14px}\n.panel-editor-tools .numeric-field{text-align:center}\n.panel-editor-tools label{gap:6px}\n.panel-editor-tools select{width:100%}\n@media(max-width:900px){.panel-editor-header-actions{flex-wrap:wrap;justify-content:flex-end}.type-secondary-grid,.tail-settings-grid{grid-template-columns:1fr}}\n'''
css.write_text(c, encoding='utf-8')
